from typing import List

from .message_handling import (Structure, SMessageAddress, SMessageHeader, SBrowserObject,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from ..utils import get_context_id, get_procedure_id
from .sack_reflection_interface import EReportingMode, EBrowserObjectName


MAX_NUM_OF_ITEMS_IN_CHANNEL_LIST_ACK_MSG = 128


class SBrowserChannel(Structure):
    _fields_ = [
        ('channel', SBrowserObject),
        ('channelState', u32),
        ('channelAddr', SMessageAddress)
    ]


@register_message
class BrowserChannelListReq(RequestMessage):
    id = 0x1b4e

    _fields_ = [
        ('header', SMessageHeader),
        ('reportingMode', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('subsystem', SBrowserObject),
        ('browserObject', SBrowserObject),
        ('objectKey2', SBrowserObject)
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserChannelListReq, self).__init__(board, cpu, *args, **kwargs)

        cell_id = kwargs['cell_id']

        self.reportingMode = EReportingMode.EReportingMode_Single
        self.contextId = get_context_id()
        self.procedureId = get_procedure_id()
        self.browserObject.objectName = EBrowserObjectName.EBrowserObjectName_Cell
        self.browserObject.objectId = cell_id


@register_message
class BrowserChannelListAck(ResponseMessage):
    id = 0x1b4f

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('channelCountTotal', u32),
        ('channelCountInThisMessage', u32),
        ('channelList', SBrowserChannel * MAX_NUM_OF_ITEMS_IN_CHANNEL_LIST_ACK_MSG)

    ]


class BrowserChannelListQuery(Query):
    def __init__(self, req, resp):
        super(BrowserChannelListQuery, self).__init__(req, resp)

        self.channels = []
        self._actual_count = 0
        self._expected_total_count = 0

    def _handle_response(self):
        self._expected_total_count = self.resp_msg.channelCountTotal
        count_in_this_message = self.resp_msg.channelCountInThisMessage
        self._actual_count += count_in_this_message
        for c in self.resp_msg.channelList[:count_in_this_message]:
            self.channels.append(c.get_copy())

    def _decide_if_complete(self):
        if self._actual_count == self._expected_total_count:
            self.complete = True


class ChannelListInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_cell_channel_list(self, board, cpu, cell_id):
        # type: (int, int, int) -> List[SBrowserChannel]
        query = BrowserChannelListQuery(BrowserChannelListReq(board, cpu, cell_id=cell_id), BrowserChannelListAck())
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()

        return query.channels
